package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var curRec PartRec

var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	if i := strings.Index(s, " "); i >= 0 {
		return s[:i]
	}
	return s
}

func MAINPARA() {
	OPENINPUT()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	CLOSEINPUT()
	SUMMARYPARA()
}

func OPENINPUT() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
	inputLines = nil
	inputIdx = 0
	f, err := os.Open("input.dat")
	if err != nil {
		// Empty file behaviour: treat as EOF on read
		inputLines = []string{}
		inputOpen = false
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// Allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, maxCap)
	for sc.Scan() {
		line := sc.Text()
		// Strip trailing \r if present (Scanner with ScanLines already strips \r? keep safe)
		line = strings.TrimSuffix(line, "\r")
		inputLines = append(inputLines, line)
	}
	inputOpen = true
}

func CLOSEINPUT() {
	inputOpen = false
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// Pad with spaces to 15 bytes on right, truncate if longer
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	s := line[11:15]
	t := strings.TrimSpace(s)
	var n int64 = 0
	if t != "" {
		// Parse digits; if contains non-digits treat non-digits as zero-ish: parse digits only
		// Build from digit chars
		var v int64 = 0
		hasDigit := false
		for _, ch := range t {
			if ch >= '0' && ch <= '9' {
				v = v*10 + int64(ch-'0')
				hasDigit = true
			}
		}
		if hasDigit {
			n = v
		} else {
			n = 0
		}
	} else {
		n = 0
	}
	curRec.LbSerial = n
}

func PROCESSPARA() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(curRec.LbPart, "A")) % 100
	// STRING ...
	part1 := delimitedBySpace(curRec.LbRegion)
	part3 := delimitedBySpace(curRec.LbPart)
	serialStr := fmt.Sprintf("%04d", curRec.LbSerial)
	// Handle overflow of serial formatting (keep low-order 4 digits)
	if len(serialStr) > 4 {
		serialStr = serialStr[len(serialStr)-4:]
	}
	concat := part1 + "-" + part3 + "-" + serialStr
	if len(concat) > 20 {
		concat = concat[:20]
	} else if len(concat) < 20 {
		concat = concat + strings.Repeat(" ", 20-len(concat))
	}
	WsLabel = concat
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	// ADD ...
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	acountStr := fmt.Sprintf("%02d", WsACount%100)
	fmt.Printf("%s A=%s\n", padRight(WsLabel, 20), acountStr)
	READPARA()
}

func SUMMARYPARA() {
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	totalStr := fmt.Sprintf("%03d", WsTotalA%1000)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}

func main() {
	MAINPARA()
}
